SOURCE_INPUTS={'wall': {'sha256': '2afabdae82b6f49988731a3499dd60a0c1ef74cf1da620e722087864ec6480c0', 'bytes': 30023, 'compressed': ''}, 'left_prop': {'sha256': '0cea29ce67afedbae5ed6990904291d1efc6c16724b00192cee29c576daaa80e', 'bytes': 12023, 'compressed': ''}, 'right_prop': {'sha256': '0cea29ce67afedbae5ed6990904291d1efc6c16724b00192cee29c576daaa80e', 'bytes': 12023, 'compressed': ''}, 'pick': {'sha256': 'f451a1de9b06365fa5630f5bcf627998908afc50b2ccf5e7c0f8e837baccbba8', 'bytes': 12509, 'compressed': ''}}
